package dev.zomboid.hordes;
import java.util.*;
public final class ScarcityPanel {
 public static String[][]rows(String[][]old,String kind){String[][]out=Arrays.copyOf(old,old.length+1);out[old.length]=kind.equals("KEYS")?ScarcityControls.KEYS:kind.equals("LABELS")?new String[]{"Loot reducido","Arma/melee por cuerpo (%)","Ropa militar por cuerpo (%)","Municion junto al arma (%)","Suministros por cuerpo (x)","Bandidos armados al nacer (%)","Bandidos con armadura (%)","Bandidos con suministros (%)","Recarga con municion saqueada","Tiempo de recarga (seg)"}:new String[]{"Limita loot NUEVO de civiles. Militares conservan equipo y vendas; mutantes tienen restos biologicos. Objetos en casillas aleatorias. No borra cuerpos guardados.","Normal 7.69% (1 de cada 13 en promedio), igual para todas las calidades. Una sola tirada: arma de fuego o melee. No se vuelve a filtrar. Equipo real siempre conservado.","Normal 7.69% (1/13): una pieza militar registrada de FracturePoint en civiles. Militares conservan TODO su equipo sin tirada. No controla objetos valiosos ni mochilas.","Normal 35% SOLO si sale un arma de fuego: pila de 2-9 balas de su calibre. Sin arma no inventa municion aleatoria. Equipo real y municion de NPC se conservan.","0-3x: comun 2, poco comun 3, raro 4, epico 5, legendario 6, mitico 7 suministros como referencia; pilas pequenas.","Normal 2%; el resto empieza con manos vacias. Solo NPC nuevos del sistema natural, no NPC de pruebas ni existentes.","Normal 2%; resto ropa civil. No transforma a los zombis ni cambia su equipo.","Normal 15%: como mucho una pequena racion o medicina inicial. Sin inventarios militares gratuitos.","Activado: NPC nuevos solo recargan con balas compatibles de su bolsa. Desactivado: recarga nativa sin este limite. El saqueo de armas y armaduras sigue activo.","0.5-10 segundos para cargar municion compatible de su bolsa. Sin balas: no recarga. No afecta NPC de pruebas."};return out;}
 public static String[]names(String[]old){String[]n=Arrays.copyOf(old,old.length+1);n[old.length]="Escasez y bandidos";return n;}
 public static String button(String old,Object screen){return ((Number)ZoneReflection.get(screen,"page")).intValue()==16?"Restaurar escasez":old;}
 @SuppressWarnings("unchecked")public static boolean preset(Object screen){if(((Number)ZoneReflection.get(screen,"page")).intValue()!=16)return false;try{ZoneReflection.call(screen,"remember");ScarcityControls.prepare((Map<String,Double>)ZoneReflection.get(screen,"draft"));ZoneReflection.call(screen,"rebuildWidgets");var f=screen.getClass().getDeclaredField("status");f.setAccessible(true);f.set(screen,"Loot escaso preparado; zombis sin cambios. Pulsa Aplicar.");}catch(Exception e){throw new IllegalStateException(e);}return true;}
 public static double scroll(String k,double v){return k.equals("loot_suministros_cantidad")?Math.max(0,Math.min(3,v)):k.equals("bandidos_recarga_segundos")?Math.max(.5,Math.min(10,v)):v;}
}
